package vn.rtr.aeris.workbench02;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class StoreTest{
 static int pass=0;static File base;interface Check{void run()throws Exception;}
 static void test(String name,Check c)throws Exception{try{c.run();pass++;System.out.println("PASS "+name);}catch(Exception e){System.out.println("FAIL "+name+" "+e);throw e;}}
 static void need(boolean b)throws Exception{if(!b)throw new Exception("ASSERT");}
 static void refuses(Check c,String message)throws Exception{try{c.run();}catch(IOException e){need(e.getMessage().contains(message));return;}throw new Exception("EXPECTED_REFUSAL "+message);}
 static WorkspaceStore store(String n)throws Exception{return new WorkspaceStore(new File(base,n),d->{},p->{});}
 public static void main(String[]args)throws Exception{base=new File(args[0]);if(!base.mkdir())throw new Exception("FIXTURE_MUST_BE_NEW");
 test("empty has no persisted authority",()->{WorkspaceStore.Snapshot s=store("empty").load();need(s.status.equals("EMPTY")&&s.head.equals("ROOT")&&s.body==null);});
 test("save restart SHA and CAS",()->{WorkspaceStore a=store("restart");WorkspaceStore.Snapshot one=a.save("ROOT","alpha");need(one.sha.equals(WorkspaceStore.sha("alpha".getBytes("UTF-8"))));WorkspaceStore b=store("restart");need(b.load().head.equals(one.head));refuses(()->b.save("ROOT","beta"),"CAS");need(b.load().body.equals("alpha"));});
 test("identical body does not consume generation",()->{WorkspaceStore a=store("same");WorkspaceStore.Snapshot s=a.save("ROOT","same");need(a.save(s.head,"same").sequence==1);});
 test("generation bound no automatic cleanup",()->{WorkspaceStore a=store("generations");String h="ROOT";for(int i=0;i<16;i++)h=a.save(h,"body"+i).head;final String old=h;refuses(()->a.save(old,"body16"),"QUOTA_RESERVE");need(new File(base,"generations").listFiles().length==17);});
 test("stricter quota never expands production limit",()->{WorkspaceStore a=new WorkspaceStore(new File(base,"quota"),d->{},p->{},1024);refuses(()->a.save("ROOT","abc"),"QUOTA_RESERVE");refuses(()->new WorkspaceStore(new File(base,"bad-quota"),d->{},p->{},WorkspaceStore.QUOTA+1),"QUOTA");});
 test("body bound before writing",()->{WorkspaceStore a=store("body-bound");char[]v=new char[WorkspaceStore.MAX_BODY+1];Arrays.fill(v,'x');refuses(()->a.save("ROOT",new String(v)),"BODY_BOUND");need(new File(base,"body-bound").listFiles().length==0);});
 test("corruption is not accepted after restart",()->{WorkspaceStore a=store("corrupt");a.save("ROOT","original");File f=Arrays.stream(new File(base,"corrupt").listFiles()).filter(p->p.getName().endsWith(".json")).findFirst().get();Files.write(f.toPath(),"changed".getBytes("UTF-8"));refuses(()->store("corrupt").load(),"BODY_SHA");});
 test("pending tail remains readonly",()->{WorkspaceStore a=store("pending");a.save("ROOT","one");Files.write(new File(base,"pending/HEAD.pending").toPath(),"partial".getBytes("UTF-8"));refuses(()->store("pending").load(),"PENDING");});
 test("rollback pointer does not hide newer body",()->{WorkspaceStore a=store("rollback");String h=a.save("ROOT","one").head;byte[]old=Files.readAllBytes(new File(base,"rollback/HEAD").toPath());a.save(h,"two");Files.write(new File(base,"rollback/HEAD").toPath(),old);refuses(()->store("rollback").load(),"ROLLBACK");});
 test("body publish fault preserves old data and latches unknown",()->{WorkspaceStore a=new WorkspaceStore(new File(base,"body-fault"),d->{},p->{if(p.equals("AFTER_BODY_BEFORE_HEAD"))throw new IOException("INJECTED");});refuses(()->a.save("ROOT","never-ack"),"INJECTED");need(new File(base,"body-fault").listFiles().length>=2);refuses(()->store("body-fault").load(),"PENDING");});
 test("fsync failure never returns commit receipt",()->{WorkspaceStore a=new WorkspaceStore(new File(base,"sync-fault"),d->{throw new IOException("SYNC_INJECTED");},p->{});refuses(()->a.save("ROOT","unknown"),"SYNC_INJECTED");refuses(()->store("sync-fault").load(),"PENDING");});
 test("rename failure preserves pending bytes",()->{WorkspaceStore a=new WorkspaceStore(new File(base,"rename-fault"),d->{},p->{if(p.startsWith("BEFORE_RENAME"))throw new IOException("RENAME_INJECTED");});refuses(()->a.save("ROOT","pending-body"),"RENAME_INJECTED");need(Arrays.stream(new File(base,"rename-fault").list()).anyMatch(n->n.endsWith(".pending")));});
 test("foreign entry refused",()->{WorkspaceStore a=store("foreign");new File(base,"foreign/other").mkdir();refuses(()->a.load(),"FOREIGN");});
 test("symlink body refused",()->{WorkspaceStore a=store("symlink");Files.createSymbolicLink(new File(base,"symlink/HEAD").toPath(),new File(base,"restart/HEAD").toPath());refuses(()->a.load(),"SYMLINK");});
 test("named root symlink refused without touching target",()->{File target=new File(base,"root-target");need(target.mkdir());File link=new File(base,"root-link");Files.createSymbolicLink(link.toPath(),target.toPath());refuses(()->store("root-link"),"ROOT_SYMLINK");need(target.listFiles().length==0);});
 test("stricter quota preserves previous committed generation",()->{WorkspaceStore a=new WorkspaceStore(new File(base,"quota-preserve"),d->{},p->{},4096);String one=String.join("",Collections.nCopies(2000,"x"));WorkspaceStore.Snapshot old=a.save("ROOT",one);refuses(()->a.save(old.head,String.join("",Collections.nCopies(2000,"y"))),"QUOTA_RESERVE");need(a.load().head.equals(old.head)&&a.load().body.equals(one));need(new File(base,"quota-preserve").listFiles().length==2);});
 test("quota below permitted minimum refused",()->{refuses(()->new WorkspaceStore(new File(base,"quota-too-small"),d->{},p->{},1023),"QUOTA");need(!new File(base,"quota-too-small").exists());});
 test("reopen under stricter quota cannot accept oversized store",()->{WorkspaceStore a=store("quota-reopen");a.save("ROOT",String.join("",Collections.nCopies(2000,"x")));WorkspaceStore b=new WorkspaceStore(new File(base,"quota-reopen"),d->{},p->{},1024);refuses(()->b.load(),"QUOTA_READONLY");need(new File(base,"quota-reopen").listFiles().length==2);});
 test("fault after head sync never returns a success receipt",()->{WorkspaceStore a=new WorkspaceStore(new File(base,"head-fault"),d->{},p->{if(p.equals("AFTER_HEAD_SYNC"))throw new IOException("HEAD_SYNC_INJECTED");});refuses(()->a.save("ROOT","possibly-durable-not-acknowledged"),"HEAD_SYNC_INJECTED");refuses(()->store("head-fault").load(),"PENDING");});
 System.out.println("SUMMARY "+pass+" HOST_JAVA_NOT_ART");}
}
